'use strict';
const ECO=window.Economy;
let catalogPage=0,packDraft={},editingPack=null;
function coinValue(c,kind='sell'){return ECO.price(state,c,kind);}
function economyRefresh(){save();if(view==='coleccion')renderCollection();if(view==='tienda')renderShop();if(view==='catalogo')renderCatalog();if(view==='especiales')renderCustomPacks();}
function saleDialog(id=null){const quick=id===null,c=quick?null:byId.get(String(id));const items=quick?ECO.excess(state):[{id:String(id),quantity:1}];if(!items.length){toast('No tenés copias excedentes de tres.');return;}const available=quick?0:Math.max(0,(state.owned[id]||0)-ECO.protectedCopies(state,String(id)));if(!quick&&!available){toast('Todas tus copias están reservadas en un mazo. Quitalas del mazo antes de vender.');return;}
 modal(`<h2>${quick?'Venta rápida · excedentes de 3':esc(c.name_es)}</h2><p>${quick?'Se venderán solo las copias que superen tres de cada carta, en toda tu colección, sin importar los filtros.':`Tenés ${state.owned[id]} copias, de las cuales ${available} se pueden vender. Valor: ${coinValue(c)} monedas por copia.`}</p>${quick?`<div class="sale-list">${items.map(i=>`<div><span>${esc(byId.get(i.id).name_es)} × ${i.quantity}</span><b>+${i.quantity*coinValue(byId.get(i.id))} ◉</b></div>`).join('')}</div>`:`<label>Copias a vender <input id="saleQuantity" type="number" value="1" min="1" max="${available}" step="1"></label><p class="micro">Las copias usadas por tus mazos quedan protegidas.</p>`}<p id="saleQuote" role="status"></p><div class="backup-actions"><button id="confirmSale" class="primary">Confirmar venta</button><button id="cancelSale">Cancelar</button></div>`);
 const selection=()=>quick?ECO.excess(state):[{id:String(id),quantity:Number($('#saleQuantity').value)}];
 const update=()=>{try{const q=ECO.quoteSale(state,cards,selection());$('#saleQuote').textContent=`${q.count} copias → +${q.coins} monedas · saldo final: ${state.coins+q.coins}`;$('#confirmSale').disabled=false;}catch(e){$('#saleQuote').textContent=e.message;$('#confirmSale').disabled=true;}};
 if(!quick)$('#saleQuantity').oninput=update;update();$('#cancelSale').onclick=()=>$('#modal').close();$('#confirmSale').onclick=()=>{try{const q=ECO.sell(state,cards,selection());deletionUndo=null;$('#undoDeletion').hidden=true;economyRefresh();$('#modal').close();toast(`Vendiste ${q.count} copias por ${q.coins} monedas`);}catch(e){toast(e.message);update();}};
}
function renderShop(){const list=state.economy.offers;$('#shopGrid').innerHTML=list.length?list.map(o=>{const c=byId.get(o.id),cost=coinValue(c,'buy');return `<article class="market-card">${tile(c)}<div class="market-meta"><b>${cost} ◉</b><span>${o.stock} disponibles</span></div><button data-shop-buy="${o.id}" ${!o.stock||state.coins<cost?'disabled':''}>Comprar una copia</button><small>Venta: ${coinValue(c)} ◉ por copia</small></article>`;}).join(''):'<p>La tienda está vacía. Elegí cartas desde «Editar tienda».</p>';$('#shopBalance').textContent=state.coins.toLocaleString('es-AR')+' monedas disponibles';$('#priceSummary').innerHTML=Object.entries(names).map(([r,n])=>`<div><span>${n}</span><b>${state.economy.prices[r].buy} / ${state.economy.prices[r].sell} ◉</b></div>`).join('');}
function buyDialog(id){const c=byId.get(id),cost=coinValue(c,'buy');modal(`<h2>Comprar ${esc(c.name_es)}</h2><p>Una copia por ${cost} monedas. Tu saldo quedará en ${state.coins-cost}.</p><button id="confirmBuy" class="primary">Comprar por ${cost} monedas</button>`);$('#confirmBuy').onclick=()=>{try{ECO.buy(state,cards,id);economyRefresh();$('#modal').close();toast('Carta agregada a tu colección');}catch(e){toast(e.message);}};}
function priceDialog(){modal(`<h2>Valores por rareza</h2><p>Se aplican a la tienda y a todas las ventas. La compra debe costar más que la venta.</p><form id="priceForm"><div class="price-table"><b>Rareza</b><b>Compra</b><b>Venta</b>${Object.entries(names).map(([r,n],i)=>`<span>${n}</span><input aria-label="Compra ${n}" data-price-rarity="${r}" data-price-kind="buy" type="number" min="1" max="100000" value="${state.economy.prices[r].buy}" required><input aria-label="Venta ${n}" data-price-rarity="${r}" data-price-kind="sell" type="number" min="0" max="10000" value="${state.economy.prices[r].sell}" required>`).join('')}</div><p id="priceError" role="alert"></p><button class="primary">Guardar valores</button></form>`);$('#priceForm').onsubmit=e=>{e.preventDefault();const next=JSON.parse(JSON.stringify(state.economy));$('#priceForm').querySelectorAll('[data-price-rarity]').forEach(input=>next.prices[input.dataset.priceRarity][input.dataset.priceKind]=Number(input.value));try{ECO.validate(next,cards);state.economy=next;economyRefresh();$('#modal').close();}catch(err){$('#priceError').textContent=err.message;}};}
function editShop(){modal('<h2>Editar tienda</h2><p>Cambiá el stock o retirala de la oferta. Para sumar otras cartas, abrí la base de datos y usá «A tienda».</p><div id="offerEditor" class="sale-list"></div><button id="shopGoCatalog" class="primary">Elegir cartas de la base de datos</button>');function rows(){$('#offerEditor').innerHTML=state.economy.offers.map(o=>`<div><span>${esc(byId.get(o.id).name_es)}</span><input aria-label="Stock ${esc(byId.get(o.id).name_es)}" data-offer-stock="${o.id}" type="number" min="0" max="100000" value="${o.stock}"><button data-withdraw="${o.id}">Retirar</button></div>`).join('')||'<p>No hay ofertas.</p>';}
 rows();$('#offerEditor').onchange=e=>{if(!e.target.dataset.offerStock)return;const n=Number(e.target.value);if(!Number.isSafeInteger(n)||n<0||n>100000){toast('Stock no válido');rows();return;}state.economy.offers.find(o=>o.id===e.target.dataset.offerStock).stock=n;economyRefresh();};$('#offerEditor').onclick=e=>{const b=e.target.closest('[data-withdraw]');if(!b)return;state.economy.offers=state.economy.offers.filter(o=>o.id!==b.dataset.withdraw);economyRefresh();rows();};$('#shopGoCatalog').onclick=()=>{$('#modal').close();showView('catalogo');};}
function addOffer(id){if(state.economy.offers.some(o=>o.id===id)){toast('Esa carta ya está en la tienda. Podés cambiar su stock desde Editar tienda.');return;}if(state.economy.offers.length>=500){toast('Límite de 500 ofertas');return;}state.economy.offers.push({id,stock:3});economyRefresh();toast('Carta agregada a la tienda con 3 copias');}
function initCatalog(){const host=$('#catalogFilters');if(host.dataset.ready)return;host.dataset.ready='true';const sidebar=$('.collection-sidebar').cloneNode(true);sidebar.setAttribute('aria-label','Filtros de base de datos');sidebar.querySelectorAll('[id]').forEach(el=>el.id='db-'+el.id);sidebar.querySelectorAll('[for]').forEach(el=>el.htmlFor='db-'+el.htmlFor);host.append(sidebar);const reset=()=>{sidebar.querySelectorAll('input').forEach(el=>{if(el.type==='checkbox')el.checked=false;else el.value='';});sidebar.querySelectorAll('select').forEach(el=>el.selectedIndex=0);catalogPage=0;};reset();host.oninput=host.onchange=()=>{catalogPage=0;renderCatalog();};$('#db-resetFilters').onclick=()=>{reset();renderCatalog();};}

function renderCatalog(){initCatalog();const filters=collectionFilters('db-'),query=window.CollectionQuery(cards,state.owned,filters),result=query.cards;$('#db-filterError').textContent=query.error;const pages=Math.max(1,Math.ceil(result.length/30));catalogPage=Math.min(catalogPage,pages-1);$('#catalogCount').textContent=`${result.length} de ${cards.length} cartas · página ${catalogPage+1} de ${pages}`;$('#catalogGrid').innerHTML=result.slice(catalogPage*30,(catalogPage+1)*30).map(c=>`<article class="market-card">${tile(filteredPrint(c,filters.set))}<small>Compra ${coinValue(c,'buy')} ◉ · Venta ${coinValue(c)} ◉</small><div class="catalog-card-actions"><button data-add-offer="${c.id}">A tienda</button><button data-add-draft="${c.id}">Al sobre</button></div></article>`).join('')||'<p>No hay cartas que coincidan.</p>';$('#catalogPrev').disabled=catalogPage===0;$('#catalogNext').disabled=catalogPage>=pages-1;$('#catalogDraftCount').textContent=Object.values(packDraft).reduce((a,b)=>a+b,0)+' copias seleccionadas para el sobre';}
function addDraft(id){packDraft[id]=Math.min(1000,(packDraft[id]||0)+1);if(view==='catalogo')renderCatalog();toast('Carta sumada al borrador del sobre');}
function renderDraft(){const ids=Object.keys(packDraft);$('#draftRows').innerHTML=ids.length?ids.map(id=>`<div class="draft-row"><img src="${esc(image(byId.get(id)))}" alt=""><span>${esc(byId.get(id).name_es)}<small>${names[byId.get(id).rarity]}</small></span><input data-draft-quantity="${id}" aria-label="Copias de ${esc(byId.get(id).name_es)}" type="number" min="1" max="1000" value="${packDraft[id]}"><button data-draft-remove="${id}" aria-label="Quitar ${esc(byId.get(id).name_es)} del sobre">×</button></div>`).join(''):'<p>Elegí cartas de la base de datos con el botón «Al sobre».</p>';$('#draftTotal').textContent=Object.values(packDraft).reduce((a,b)=>a+b,0)+' copias en la caja especial';}
function renderCustomPacks(){renderDraft();$('#customPackList').innerHTML=state.economy.customPacks.map(p=>{const remaining=p.entries.reduce((n,e)=>n+e.remaining,0),total=p.entries.reduce((n,e)=>n+e.copies,0);return `<article class="custom-product"><h2>${esc(p.name)}</h2><p>${p.size} cartas por sobre · ${p.cost} ◉</p><p>${remaining} / ${total} cartas restantes · ${Math.ceil(remaining/p.size)} sobres</p>${remaining&&remaining<p.size?`<p class="micro">Último sobre: ${remaining} cartas por ${p.cost} monedas.</p>`:''}<div class="backup-actions"><button class="primary" data-open-custom="${p.id}" ${!remaining||state.coins<p.cost?'disabled':''}>Abrir · ${p.cost} ◉</button><button data-view-custom="${p.id}">Contenido</button><button data-edit-custom="${p.id}">Editar</button><button data-reset-custom="${p.id}">Reponer caja</button><button data-delete-custom="${p.id}">Eliminar</button></div></article>`;}).join('')||'<p>Todavía no hay sobres especiales. Creá el primero con el editor.</p>';}
function saveCustom(){try{const name=$('#customName').value.trim(),cost=Number($('#customCost').value),size=Number($('#customSize').value),id=editingPack||'custom-'+crypto.randomUUID();const pack={id,name,cost,size,entries:Object.entries(packDraft).map(([id,copies])=>({id,copies,remaining:copies}))};const next=JSON.parse(JSON.stringify(state.economy));next.customPacks=next.customPacks.filter(p=>p.id!==id);next.customPacks.push(pack);ECO.validate(next,cards);state.economy=next;packDraft={};editingPack=null;$('#customName').value='';$('#draftNotice').textContent='';economyRefresh();toast('Sobre guardado y caja llena');}catch(e){$('#draftNotice').textContent=e.message;}}
function customContent(id){const p=state.economy.customPacks.find(p=>p.id===id);modal(`<h2>${esc(p.name)}</h2><p>Copias restantes / iniciales. Cada copia restante tiene la misma probabilidad de salir.</p><div class="sale-list">${p.entries.map(e=>`<div><button data-card="${e.id}">${esc(byId.get(e.id).name_es)}</button><span>${e.remaining} / ${e.copies}</span></div>`).join('')}</div>`);}
function openCustom(id){if(packOpening)return;try{const p=state.economy.customPacks.find(p=>p.id===id);const list=sortPack(ECO.draw(state,cards,id,random).map(id=>byId.get(id)));lastPack=list;save();renderCustomPacks();$('#results').hidden=false;$('#packGrid').innerHTML=list.map(c=>tile(c)).join('');$('#lastSet').textContent=p.name+' · '+list.length+' cartas agregadas';startPackReveal(list,p.name);}catch(e){toast(e.message);}}
$('#quickSell').onclick=()=>saleDialog();$('#shopPrices').onclick=priceDialog;$('#shopEdit').onclick=editShop;
$('#catalogPrev').onclick=()=>{catalogPage--;renderCatalog();};$('#catalogNext').onclick=()=>{catalogPage++;renderCatalog();};
$('#saveCustom').onclick=saveCustom;$('#clearDraft').onclick=()=>{packDraft={};editingPack=null;$('#customName').value='';$('#draftNotice').textContent='';renderDraft();};
$('#draftRows').onchange=e=>{if(!e.target.dataset.draftQuantity)return;const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>1000){toast('Elegí entre 1 y 1.000 copias');renderDraft();return;}packDraft[e.target.dataset.draftQuantity]=n;renderDraft();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.shopBuy)buyDialog(d.shopBuy);if(d.addOffer)addOffer(d.addOffer);if(d.addDraft)addDraft(d.addDraft);if(d.draftRemove){delete packDraft[d.draftRemove];renderDraft();}if(d.openCustom)openCustom(d.openCustom);if(d.viewCustom)customContent(d.viewCustom);if(d.editCustom){const p=state.economy.customPacks.find(p=>p.id===d.editCustom);editingPack=p.id;packDraft=Object.fromEntries(p.entries.map(e=>[e.id,e.copies]));$('#customName').value=p.name;$('#customCost').value=p.cost;$('#customSize').value=p.size;$('#draftNotice').textContent='Al guardar los cambios se repone el contenido completo de esta caja.';renderDraft();$('#customEditor').scrollIntoView({behavior:'smooth'});}if(d.resetCustom||d.deleteCustom){const id=d.resetCustom||d.deleteCustom,p=state.economy.customPacks.find(p=>p.id===id),reset=!!d.resetCustom;modal(`<h2>${reset?'Reponer':'Eliminar'} ${esc(p.name)}</h2><p>${reset?'Se restauran todas las copias de esta caja.':'Se elimina este producto del listado.'} Las cartas obtenidas se conservan.</p><button id="confirmCustomAction">${reset?'Reponer caja':'Eliminar sobre'}</button>`);$('#confirmCustomAction').onclick=()=>{if(reset)p.entries.forEach(e=>e.remaining=e.copies);else state.economy.customPacks=state.economy.customPacks.filter(p=>p.id!==id);economyRefresh();$('#modal').close();};}});
